input.command:
python3 - <<'EOF'
import shutil, os, pathlib
E = pathlib.Path("/tmp/eval-head")
if E.exists(): shutil.rmtree(E)
src = pathlib.Path("/workspace")
for d in [".claude/adapters", ".claude/defaults", ".claude/scripts", "tests/unit", "tools"]:
    s = src / d
    if s.exists():
        shutil.copytree(s, E / d, ignore=shutil.ignore_patterns("__pycache__", ".pytest_cache"))
for f in [".loa.config.yaml.example", ".loa.config.yaml"]:
    if (src / f).exists(): shutil.copy2(src / f, E / f)
head = src / "pr/head"
n = 0
for p in head.rglob("*"):
    if p.is_file() and ".claude/skills" not in str(p):
        rel = p.relative_to(head)
        (E / rel).parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(p, E / rel); n += 1
print("overlaid", n, "files into", E)
EOF
ls /tmp/eval-head /tmp/eval-head/.claude

