cd /workspace; grep -n 'headless_connect_floor' .claude/adapters/loa_cheval/types.py pr/base/.claude/adapters/loa_cheval/types.py pr/head/.claude/adapters/loa_cheval/types.py .claude/adapters/loa_cheval/providers/headless_cli.py | head; echo "---base vs repo types identical?"; cmp .claude/adapters/loa_cheval/types.py pr/base/.claude/adapters/loa_cheval/types.py && echo same; echo "--- git log for headless_cli"; git log --oneline -3 -- .claude/adapters/loa_cheval/providers/headless_cli.py; echo "--- other imports from types in repo not in head types"; python3 - <<'EOF'
import re,glob
head=open('/workspace/pr/head/.claude/adapters/loa_cheval/types.py').read()
names=set(re.findall(r'^(?:class|def) (\w+)',head,re.M))|set(re.findall(r'^(\w+)\s*=',head,re.M))
missing=set()
for f in glob.glob('/workspace/.claude/adapters/**/*.py',recursive=True):
    s=open(f).read()
    for m in re.finditer(r'from loa_cheval\.types import \(([^)]*)\)',s,re.S):
        for n in re.findall(r'\b(\w+)\b',m.group(1)):
            if n not in names and n not in ('as',): missing.add((n,f.split('/adapters/')[1]))
    for m in re.finditer(r'from loa_cheval\.types import ([^\n(]+)',s):
        for n in re.findall(r'\b(\w+)\b',m.group(1)):
            if n not in names and n not in ('as',): missing.add((n,f.split('/adapters/')[1]))
print(sorted(missing))
EOF

